args.CommandLine:
node -e "
const fs = require('fs');
const readline = require('readline');
const rl = readline.createInterface({ input: fs.createReadStream('temp_sat_dump.txt') });
rl.on('line', line => {
  try {
    const step = JSON.parse(line);
    const text = typeof step.content === 'string' ? step.content : JSON.stringify(step);
    if (text.includes('COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM')) {
      console.log('Match found in step index:', step.step_index);
      fs.writeFileSync('matched_step.json', text);
    }
  } catch (e) {}
});
"
